package main

import (
  "context"
  "errors"
  "testing"
  "time"
)

func TestEvalCheckResults(t *testing.T) {
  p := New(4, 16)
  defer p.Shutdown()
  jobs := make([]func() int, 20)
  for i := range jobs {
    i := i
    jobs[i] = func() int { time.Sleep(time.Duration(20-i) * time.Millisecond); return i * 2 }
  }
  got, err := p.Submit(context.Background(), jobs)
  if err != nil {
    t.Fatalf("submit: %v", err)
  }
  if len(got) != 20 {
    t.Fatalf("got %d results", len(got))
  }
  for i, v := range got {
    if v != i*2 {
      t.Fatalf("result %d = %d, want %d (order)", i, v, i*2)
    }
  }
}

func TestEvalCheckCancel(t *testing.T) {
  p := New(1, 1)
  defer p.Shutdown()
  ctx, cancel := context.WithCancel(context.Background())
  cancel()
  jobs := []func() int{func() int { time.Sleep(5 * time.Second); return 1 }}
  _, err := p.Submit(ctx, jobs)
  if !errors.Is(err, context.Canceled) {
    t.Fatalf("expected context.Canceled, got %v", err)
  }
}

