package main

import (
  "testing"
  "time"
)

type fakeClock struct{ t time.Time }

func (f *fakeClock) Now() time.Time { return f.t }

func TestEvalCheckLimiter(t *testing.T) {
  fc := &fakeClock{t: time.Now()}
  l := NewLimiter(2, 3, fc)
  for i := 0; i < 3; i++ {
    if !l.Allow() {
      t.Fatalf("burst event %d denied", i)
    }
  }
  if l.Allow() {
    t.Fatal("sustained use must throttle")
  }
  fc.t = fc.t.Add(1500 * time.Millisecond)
  if !l.Allow() {
    t.Fatal("refill after 1.5s at rate 2/s must allow")
  }
}
